import{_ as t,o as a,c as i,ah as o}from"./chunks/framework.CRsDMGp2.js";const h=JSON.parse('{"title":"Guide — Client","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/client.md","filePath":"src/en/guide/client.md"}'),n={name:"en/guide/client.md"};function r(l,e,s,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="guide-—-client" tabindex="-1">Guide — Client <a class="header-anchor" href="#guide-—-client" aria-label="Permalink to &quot;Guide — Client&quot;">​</a></h1><p>Track your projects, approve deliverables, pay your invoices.</p><h2 id="your-dashboard" tabindex="-1">Your dashboard <a class="header-anchor" href="#your-dashboard" aria-label="Permalink to &quot;Your dashboard&quot;">​</a></h2><p>After signing in, your dashboard brings together:</p><ul><li>your total number of projects, by status (active, suspended, completed);</li><li>your reached and pending milestones;</li><li>your recent projects, with direct access to their page;</li><li>your upcoming invoices, with overdue ones highlighted;</li><li>documents awaiting your approval.</li></ul><h2 id="tracking-a-project-s-progress" tabindex="-1">Tracking a project&#39;s progress <a class="header-anchor" href="#tracking-a-project-s-progress" aria-label="Permalink to &quot;Tracking a project&#39;s progress&quot;">​</a></h2><p>On a project&#39;s page, the navigation on the left groups information by theme:</p><ul><li><strong>Tracking</strong> — the project&#39;s phases and their milestones, a Gantt view of the whole, and the detail of ongoing tasks.</li><li><strong>Collaboration</strong> — shared documents, the team assigned to your project, and messaging.</li><li><strong>Finance</strong> — signatures to complete, billing, and, once formalized, any amendment.</li></ul><p>Whenever a non-billable milestone is reached, your project manager can leave a <strong>report</strong> visible from the Tracking tab. Some milestones also include a <strong>preview link</strong> to a working version of the project at that stage, when relevant to your project type.</p><h2 id="documents-and-deliverables" tabindex="-1">Documents and deliverables <a class="header-anchor" href="#documents-and-deliverables" aria-label="Permalink to &quot;Documents and deliverables&quot;">​</a></h2><p>From your project&#39;s <strong>Documents</strong> tab:</p><ul><li>view documents and deliverables shared by the project team;</li><li>upload your own documents (specifications, administrative files, feedback);</li><li>approve a deliverable or leave a comment directly from its page — the project team is notified of your decision.</li></ul><h2 id="electronic-signature" tabindex="-1">Electronic signature <a class="header-anchor" href="#electronic-signature" aria-label="Permalink to &quot;Electronic signature&quot;">​</a></h2><p>Some documents require your electronic signature, from the <strong>Signatures</strong> tab:</p><ul><li>the <strong>delivery note</strong>, when a deliverable or piece of equipment is handed over;</li><li>the <strong>completion certificate</strong>, when the project closes;</li><li>any <strong>amendment</strong>, once it has been formalized by the administrator (the tab only appears at that point, not while it&#39;s being drafted).</li></ul><h2 id="billing-and-payment" tabindex="-1">Billing and payment <a class="header-anchor" href="#billing-and-payment" aria-label="Permalink to &quot;Billing and payment&quot;">​</a></h2><p>From the <strong>Billing</strong> tab:</p><ul><li>view your project&#39;s payment schedule and the status of each installment (upcoming, due, paid);</li><li>download your invoices (deposit, intermediate, balance or equipment, depending on the case) — you&#39;re notified when they&#39;re sent, with a reminder before the due date;</li><li>pay an invoice directly from the platform via Mobile Money (Flooz, T-Money) or card, or declare a payment made by regular bank transfer.</li></ul><div class="warning custom-block"><p class="custom-block-title">Unpaid invoice</p><p>If an invoice remains unpaid past the agreed period, access to your project can be suspended by your project manager or the administrator, until the situation is resolved.</p></div><h2 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h2><p>Talk with the project team via the built-in messaging, without leaving the platform. You receive automatic notifications at key steps: milestone reached, deliverable submitted, delay reported, payment due.</p>',21)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
